referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const out = [];
  let total = 0;
  for (const group of d) {
    if (group.length === 0) {
      out.push(total);
      total = 0;
    } else for (const n of group) total += n;
  }
  return out;
}

referenceSolutions.typescript:
type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const out: number[] = [];
  let total = 0;
  for (const group of d) {
    if (group.length === 0) {
      out.push(total);
      total = 0;
    } else for (const n of group) total += n;
  }
  return out;
}
